import{_ as e,o as s,c as n,S as l}from"./chunks/framework.D1Ss-Xl7.js";const b=JSON.parse('{"title":"Sublime使用笔记以及插件推荐","description":"","frontmatter":{"title":"Sublime使用笔记以及插件推荐","date":"2013-07-02 22:06","comments":true,"archives":2013,"tags":["sublime"]},"headers":[],"relativePath":"posts/2013-07-02-sublime-text2-plugins/index.md","filePath":"posts/2013/2013-07-02-Sublime-Text2-plugins.md"}'),o={name:"posts/2013-07-02-sublime-text2-plugins/index.md"};function t(r,a,p,i,c,u){return s(),n("div",null,[...a[0]||(a[0]=[l(`<p>自从换了 Linux 就摆脱了笨重的 VS 这个强大的开发工具,自动提示,自动纠错.... VS 为我提供了太多功能,已经把我宠坏了...以至于普通的编辑器我都无法习惯... 这样可不是什么好习惯,不过 Sublime Text 2 是个很好的编辑器,特别是它的插件特别 丰富提供了很多实用的功能.于是在 Linux 下前端开发基本就是实用它了. 虽说是收费软件,但是个人用户可以无限期的免费试用,只不过经常提示购买罢了...</p><h2 id="基础配置" tabindex="-1">基础配置 <a class="header-anchor" href="#基础配置" aria-label="Permalink to &quot;基础配置&quot;">​</a></h2><p>个人喜欢亮色系的输入环境于是换成 Dawn 主题,并且修改了字体和大小</p><div class="language-json line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">{</span></span>
<span class="line"><span style="color:#005CC5;">  &quot;color_scheme&quot;</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&quot;Packages/Color Scheme - Default/Dawn.tmTheme&quot;</span><span style="color:#24292E;">,</span></span>
<span class="line"><span style="color:#005CC5;">  &quot;font_face&quot;</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&quot;Deja Vu Sans Mono&quot;</span><span style="color:#24292E;">,</span></span>
<span class="line"><span style="color:#005CC5;">  &quot;font_size&quot;</span><span style="color:#24292E;">: </span><span style="color:#005CC5;">11.5</span><span style="color:#24292E;">,</span></span>
<span class="line"><span style="color:#005CC5;">  &quot;ignored_packages&quot;</span><span style="color:#24292E;">: [</span><span style="color:#032F62;">&quot;Vintage&quot;</span><span style="color:#24292E;">]</span></span>
<span class="line"><span style="color:#24292E;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h2 id="输入法问题解决" tabindex="-1">输入法问题解决 <a class="header-anchor" href="#输入法问题解决" aria-label="Permalink to &quot;输入法问题解决&quot;">​</a></h2><p>如果大家和我一样使用的输入法是 fcitx 的话可以使用 fcitx 官方提供的解决办法<a href="https://fcitx-im.org/wiki/Hall_of_Shame_for_Linux_IME_Support" target="_blank" rel="noreferrer">Hall_of_Shame_for_Linux_IME_Support</a> 按照那个<a href="http://www.sublimetext.com/forum/viewtopic.php?f=3&amp;t=7006&amp;sid=50cfea9b8fb28114867fc217f47daf8a&amp;start=10#p41343" target="_blank" rel="noreferrer">帖子</a>三个步骤便可以成功调出输入法.</p><h2 id="常用插件推荐" tabindex="-1">常用插件推荐 <a class="header-anchor" href="#常用插件推荐" aria-label="Permalink to &quot;常用插件推荐&quot;">​</a></h2><h3 id="package-control" tabindex="-1">Package Control <a class="header-anchor" href="#package-control" aria-label="Permalink to &quot;Package Control&quot;">​</a></h3><p>Package Control 是用来管理 Sublime Text 2 的插件的插件. 也是装完后第一个要安装的插件. 首先打开 console, 并在打开的 Sublime console 中输入:</p><div class="language-py line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">py</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">import</span><span style="color:#24292E;"> urllib2,os; pf=</span><span style="color:#032F62;">&#39;Package Control.sublime-package&#39;</span><span style="color:#24292E;">; ipp=sublime.installed_packages_path(); os.makedirs(ipp) </span><span style="color:#D73A49;">if</span><span style="color:#D73A49;"> not</span><span style="color:#24292E;"> os.path.exists(ipp) </span><span style="color:#D73A49;">else</span><span style="color:#005CC5;"> None</span><span style="color:#24292E;">; urllib2.install_opener(urllib2.build_opener(urllib2.ProxyHandler())); </span><span style="color:#005CC5;">open</span><span style="color:#24292E;">(os.path.join(ipp,pf),</span><span style="color:#032F62;">&#39;wb&#39;</span><span style="color:#24292E;">).write(urllib2.urlopen(</span><span style="color:#032F62;">&#39;http://sublime.wbond.net/&#39;</span><span style="color:#D73A49;">+</span><span style="color:#24292E;">pf.replace(</span><span style="color:#032F62;">&#39; &#39;</span><span style="color:#24292E;">,</span><span style="color:#032F62;">&#39;%20&#39;</span><span style="color:#24292E;">)).read()); </span><span style="color:#005CC5;">print</span><span style="color:#032F62;"> &#39;Please restart Sublime Text to finish installation&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="zencoding" tabindex="-1">ZenCoding <a class="header-anchor" href="#zencoding" aria-label="Permalink to &quot;ZenCoding&quot;">​</a></h3><p>Zen Coding 是为了高速 HTML 编程和编辑开发的插件。这个插件的核心是一个超级强大的缩略词引擎，允许你扩展表达式到 HTML 代码中，类似于 CSS 的选择器。 通过 <code>Ctrl+,</code> 进行代码展开</p><p><strong>Zen Coding 现在已经被 Emmet 替代(Zen Coding 已经从 Sublime Text 2 的插件源中移除)，直接在编辑器内输入表达式，按下 Tab 即可扩展。</strong></p><h3 id="jquery-package-for-sublime-text" tabindex="-1">jQuery Package for Sublime Text <a class="header-anchor" href="#jquery-package-for-sublime-text" aria-label="Permalink to &quot;jQuery Package for Sublime Text&quot;">​</a></h3><p>这个毫无疑问，没有 jQuery 我们还能干什么？绝对不错的 jQuery 开发插件，个人来说非常喜欢.</p><h3 id="js-format" tabindex="-1">JS Format <a class="header-anchor" href="#js-format" aria-label="Permalink to &quot;JS Format&quot;">​</a></h3><p>JS format 是 Sublime Text 2 的一个 javascript 的格式化插件，使用来自 JS beautifier 的命令行/python 模块的 javascript 格式来格式化选择的文本，或者整个文件. 不过貌似格式化部分文本会出现问题</p><h3 id="sublime-codeintel" tabindex="-1">Sublime CodeIntel <a class="header-anchor" href="#sublime-codeintel" aria-label="Permalink to &quot;Sublime CodeIntel&quot;">​</a></h3><p>是一个想法来自于 Komodo 编辑器的智能插件. 帮助你实时展示存在模块的自动补齐信息，同时也展示目前方法的信息到状态栏中. 自动补全超赞的!</p><h3 id="tag" tabindex="-1">Tag <a class="header-anchor" href="#tag" aria-label="Permalink to &quot;Tag&quot;">​</a></h3><p>当你需要处理标签时，Tag 是一个伟大的插件.</p><h2 id="解决中文编码问题" tabindex="-1">解决中文编码问题 <a class="header-anchor" href="#解决中文编码问题" aria-label="Permalink to &quot;解决中文编码问题&quot;">​</a></h2><p><a href="https://github.com/seanliang/ConvertToUTF8" target="_blank" rel="noreferrer">ConvertToUTF8</a><a href="https://github.com/seanliang/Codecs26" target="_blank" rel="noreferrer">Codecs26</a> 同时装这两个插件就可以正常打开 GBK 文件并且保存.</p><h2 id="一些编码规范" tabindex="-1">一些编码规范 <a class="header-anchor" href="#一些编码规范" aria-label="Permalink to &quot;一些编码规范&quot;">​</a></h2><p>有时候会设置保存文件时删除多余的空白字符并且在文件结尾添加空白行</p><p>打开 Preferences-&gt;Settings-Default 设置</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>&quot;trim_trailing_white_space_on_save&quot;: true,</span></span>
<span class="line"><span>&quot;ensure_newline_at_eof_on_save&quot;: true,</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div>`,27)])])}const h=e(o,[["render",t]]);export{b as __pageData,h as default};
